if (typeof result !== "string") throw new Error("Expected CSV text");
const lines = result.trim().split("\n");
const rows=lines.slice(1).map(line=>{const [truckId,at,lat,lon,engineOn,odometer]=line.split(",");return {line,truckId,at,lat:Number(lat),lon:Number(lon)};});
text({source:"telematics/68.csv",header:lines[0],rowCount:rows.length,truck29:rows.filter(r=>r.truckId==="29").map(r=>r.line)});
const windowRows=rows.filter(r=>r.at>="2026-10-02T14:04:30Z" && r.at<="2026-10-02T14:24:30Z");
const rad=d=>d*Math.PI/180;
const distance=r=>{const a=Math.sin(rad(r.lat-27.8828)/2)**2+Math.cos(rad(27.8828))*Math.cos(rad(r.lat))*Math.sin(rad(r.lon+98.6178)/2)**2;return 6371000*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a));};
text({windowRowCount:windowRows.length,within3000mInWindow:windowRows.filter(r=>distance(r)<=3000).map(r=>r.line),closestInWindow:windowRows.slice().sort((a,b)=>distance(a)-distance(b)).slice(0,3).map(r=>r.line),closestAllDay:rows.slice().sort((a,b)=>distance(a)-distance(b)).slice(0,3).map(r=>r.line)});
